select c.segment, c.age, t.closed_balance, t.pct_frozen from customers c left join (select customer_id, sum(case when status = 'CLOSED' then balance else 0 end) as closed_balance, round((100 * sum(case when status = 'FROZEN' then 1 else 0 end)) / count(*), 1) as pct_frozen from accounts where account_type not in ('CHECKING', 'SAVINGS') group by customer_id) t on c.id = t.customer_id where t.closed_balance >= 20 order by c.age desc
